"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";
import type { ComponentProps } from "react";
import { TextMorph } from "torph/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { createOrbRenderer, drawOrbStill } from "./voice-orb-gl";
import type { OrbLook, OrbRenderer } from "./voice-orb-gl";

/* ─────────────────────────────────────────────────────────────────────────
 * Voice orb. A voice assistant's presence: a ball of points whose look
 * follows what the assistant is doing, a status in the middle, and one
 * button to talk.
 *
 *   idle        a thin, quiet shell                       "Ask me anything"
 *   listening   fine points that stir with your voice     "Listening…"
 *   thinking    dims and breathes, no voice               "Thinking…"
 *   speaking    brighter, thicker, pulsing with speech    "Speaking"
 *   playing     the ball wobbles, a pastel rim            "Now playing" + title
 *
 * Every state is the same points with different numbers (LOOKS below). On a
 * change each number eases to its target over about 0.7s, so nothing cuts:
 * that's the whole motion design. The voice level (0–1, from your audio or
 * the built-in demo) pushes size, depth and brightness on top.
 *
 * Without a `state` prop the block runs a demo when you press the button:
 * listening 3s → thinking 1.8s → speaking 5.2s → playing 6s → idle.
 * ───────────────────────────────────────────────────────────────────────── */

export type VoiceState =
  | "idle"
  | "listening"
  | "thinking"
  | "speaking"
  | "playing";

/** Each state's look. Tune here; the shader reads these names. */
const LOOKS: Record<VoiceState, OrbLook> = {
  idle: {
    breath: 0,
    bright: 0.75,
    drift: 0.006,
    front: 0.1,
    iris: 0,
    levelGain: 0,
    radius: 0.76,
    rimPower: 1.6,
    ripple: 0,
    size: 1.5,
    spin: 0.025,
    thickness: 0.035,
    twinkle: 0.45,
    wobble: 0,
  },
  listening: {
    breath: 0,
    bright: 0.72,
    drift: 0.008,
    front: 0.12,
    iris: 0,
    levelGain: 0.7,
    radius: 0.76,
    rimPower: 1.4,
    ripple: 0.6,
    size: 1.45,
    spin: 0.035,
    thickness: 0.04,
    twinkle: 0.4,
    wobble: 0,
  },
  playing: {
    breath: 0,
    bright: 1,
    drift: 0.012,
    front: 0.1,
    iris: 0.75,
    levelGain: 0.8,
    radius: 0.78,
    rimPower: 1.1,
    ripple: 0.5,
    size: 2.2,
    spin: 0.05,
    thickness: 0.1,
    twinkle: 0.35,
    wobble: 0.1,
  },
  speaking: {
    breath: 0,
    bright: 1,
    drift: 0.01,
    front: 0.07,
    iris: 0,
    levelGain: 1,
    radius: 0.77,
    rimPower: 1.25,
    ripple: 1,
    size: 2,
    spin: 0.04,
    thickness: 0.085,
    twinkle: 0.35,
    wobble: 0.015,
  },
  thinking: {
    breath: 1,
    bright: 0.45,
    drift: 0.005,
    front: 0.14,
    iris: 0,
    levelGain: 0,
    radius: 0.75,
    rimPower: 1.7,
    ripple: 0,
    size: 1.25,
    spin: 0.09,
    thickness: 0.025,
    twinkle: 0.7,
    wobble: 0,
  },
};

/** What reduced motion keeps: the look's light, none of its movement. */
const STILL = {
  breath: 0,
  drift: 0,
  ripple: 0,
  spin: 0,
  twinkle: 0,
  wobble: 0,
} satisfies Partial<OrbLook>;

const EASE = {
  /** Voice level, rising: fast, so a syllable lands on time. */
  attack: 22,
  /** Look numbers: ~95% of the way in 0.7s, no overshoot. */
  look: 4.2,
  /** Voice level, falling: slower, so speech reads as phrases. */
  release: 7,
};

/** The text each state shows when no `label` is given. */
const LABELS: Record<VoiceState, string> = {
  idle: "Ask me anything",
  listening: "Listening…",
  playing: "Now playing",
  speaking: "Speaking",
  thinking: "Thinking…",
};

const TEXT_MORPH = { duration: 320, ease: "cubic-bezier(0.23, 1, 0.32, 1)" };

/** A level: a number, or a function the orb reads every frame. */
export type VoiceLevel = number | (() => number);

const readLevel = (level: VoiceLevel | undefined) => {
  const value = typeof level === "function" ? level() : (level ?? 0);
  return Number.isFinite(value) ? Math.min(Math.max(value, 0), 1) : 0;
};

const approach = (from: number, to: number, rate: number, dt: number) =>
  from + (to - from) * (1 - Math.exp(-rate * dt));

// ── Colour ───────────────────────────────────────────────────────────────
// The points take the element's CSS `color`, which can be any format
// (Tailwind v4 colours are oklch), so a 1px canvas turns it into RGB.
let swatch: CanvasRenderingContext2D | null = null;

const toRgb = (css: string): [number, number, number] => {
  swatch ??= document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true });
  if (!swatch) {
    return [1, 1, 1];
  }
  swatch.clearRect(0, 0, 1, 1);
  swatch.fillStyle = css;
  swatch.fillRect(0, 0, 1, 1);
  const [r, g, b] = swatch.getImageData(0, 0, 1, 1).data;
  return [r / 255, g / 255, b / 255];
};

/** The element's text colour as RGB, re-read when the theme changes. */
const useCssColor = (ref: React.RefObject<HTMLElement | null>) => {
  const color = useRef<[number, number, number]>([1, 1, 1]);
  useEffect(() => {
    const read = () => {
      if (ref.current) {
        color.current = toRgb(getComputedStyle(ref.current).color);
      }
    };
    read();
    const observer = new MutationObserver(read);
    observer.observe(document.documentElement, {
      attributeFilter: ["class", "style", "data-theme"],
      attributes: true,
    });
    const scheme = matchMedia("(prefers-color-scheme: dark)");
    scheme.addEventListener("change", read);
    return () => {
      observer.disconnect();
      scheme.removeEventListener("change", read);
    };
  }, [ref]);
  return color;
};

// ── The orb ──────────────────────────────────────────────────────────────

export interface ParticleOrbProps extends ComponentProps<"div"> {
  /** What the assistant is doing; the look eases to it. */
  state?: VoiceState;
  /** Voice level 0–1, or a function read every frame (e.g. an analyser). */
  level?: VoiceLevel;
}

interface Loop {
  look: OrbLook;
  level: number;
  spin: number;
  time: number;
}

/** Eases the running look and level one frame towards their targets. */
const stepLoop = (
  loop: Loop,
  target: OrbLook,
  level: number,
  dt: number,
  still: boolean
) => {
  for (const key of Object.keys(target) as (keyof OrbLook)[]) {
    loop.look[key] = still
      ? target[key]
      : approach(loop.look[key], target[key], EASE.look, dt);
  }
  const rate = level > loop.level ? EASE.attack : EASE.release;
  loop.level = approach(loop.level, level, rate, dt);
  if (!still) {
    loop.time += dt;
    loop.spin += dt * loop.look.spin * Math.PI * 2;
  }
};

/**
 * The ball of points alone, filling its box (keep the box square). Its
 * points take the box's text colour: set `text-*` or `color` on it.
 */
export const ParticleOrb = ({
  className,
  level,
  state = "idle",
  ...props
}: ParticleOrbProps) => {
  const boxRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const color = useCssColor(boxRef);
  const reduced = useReducedMotion() ?? false;
  const [fallback, setFallback] = useState(false);

  // Props the frame loop reads without restarting.
  const live = useRef({ level, reduced, state });
  live.current = { level, reduced, state };

  useEffect(() => {
    const canvas = canvasRef.current;
    const box = boxRef.current;
    if (!(canvas && box)) {
      return;
    }
    let renderer: OrbRenderer | null = createOrbRenderer(canvas);
    if (!renderer) {
      setFallback(true);
      return;
    }
    const start = live.current;
    const loop: Loop = {
      level: 0,
      look: { ...LOOKS[start.state], ...(start.reduced ? STILL : {}) },
      spin: 0.6,
      time: 0,
    };
    let frame = 0;
    let last = 0;
    let visible = true;

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const { height, width } = box.getBoundingClientRect();
      renderer?.resize(
        Math.max(1, Math.round(width * dpr)),
        Math.max(1, Math.round(height * dpr)),
        Math.min(width, height)
      );
    };

    const tick = (now: number) => {
      const dt = last ? Math.min((now - last) / 1000, 0.05) : 0;
      last = now;
      const { level: input, reduced: still, state: goal } = live.current;
      const target = still ? { ...LOOKS[goal], ...STILL } : LOOKS[goal];
      stepLoop(loop, target, still ? 0 : readLevel(input), dt, still);
      renderer?.draw({ ...loop, color: color.current });
      frame = requestAnimationFrame(tick);
    };

    const run = () => {
      cancelAnimationFrame(frame);
      last = 0;
      if (visible && !document.hidden && renderer) {
        frame = requestAnimationFrame(tick);
      }
    };

    const sizes = new ResizeObserver(resize);
    sizes.observe(box);
    const view = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true;
      run();
    });
    view.observe(box);
    const lost = (event: Event) => {
      event.preventDefault();
      cancelAnimationFrame(frame);
      renderer = null;
    };
    const restored = () => {
      renderer = createOrbRenderer(canvas);
      resize();
      run();
    };
    canvas.addEventListener("webglcontextlost", lost);
    canvas.addEventListener("webglcontextrestored", restored);
    document.addEventListener("visibilitychange", run);
    resize();
    run();

    return () => {
      cancelAnimationFrame(frame);
      sizes.disconnect();
      view.disconnect();
      canvas.removeEventListener("webglcontextlost", lost);
      canvas.removeEventListener("webglcontextrestored", restored);
      document.removeEventListener("visibilitychange", run);
      renderer?.dispose();
    };
  }, [color]);

  // No WebGL2: one still drawing, redrawn when the state or size changes.
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!(fallback && canvas)) {
      return;
    }
    const draw = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(canvas.clientWidth * dpr);
      canvas.height = Math.round(canvas.clientHeight * dpr);
      drawOrbStill(canvas, color.current, LOOKS[state]);
    };
    draw();
    const sizes = new ResizeObserver(draw);
    sizes.observe(canvas);
    return () => sizes.disconnect();
  }, [color, fallback, state]);

  return (
    <div
      aria-hidden
      className={cn("relative", className)}
      data-slot="particle-orb"
      ref={boxRef}
      {...props}
    >
      <canvas className="absolute inset-0 size-full" ref={canvasRef} />
    </div>
  );
};

// ── Voice level sources ──────────────────────────────────────────────────

/** A made-up speech level: syllables in phrases, with pauses between. */
export const speechLevel = (t: number) => {
  const phrase = 0.5 + 0.5 * Math.sin(t * 1.25) + 0.3 * Math.sin(t * 0.41);
  const gate = Math.min(Math.max((phrase - 0.2) / 0.35, 0), 1);
  const syllable =
    Math.abs(Math.sin(t * Math.PI * 3.3 + 1.6 * Math.sin(t * 1.1))) ** 1.4;
  const grain = 0.75 + 0.25 * Math.sin(t * 17.3) * Math.sin(t * 7.1);
  return gate * syllable * grain;
};

/** A made-up music level: a slow swell with a soft beat on top. */
export const musicLevel = (t: number) =>
  Math.min(
    1,
    0.45 +
      0.25 * Math.sin(t * 2.2) * Math.sin(t * 0.9) +
      0.3 * Math.max(0, Math.sin(t * Math.PI * 2.2)) ** 6
  );

type MicStatus = "off" | "starting" | "on" | "blocked";

/**
 * The microphone's level, 0–1, as a function to pass to `level`. Asks for
 * the mic while `enabled`; `status` says whether it's on or was blocked.
 */
export const useMicLevel = (enabled: boolean) => {
  const analyser = useRef<AnalyserNode | null>(null);
  const buffer = useRef<Float32Array<ArrayBuffer> | null>(null);
  const [status, setStatus] = useState<MicStatus>("off");

  useEffect(() => {
    if (!enabled) {
      return;
    }
    let cancelled = false;
    let stream: MediaStream | null = null;
    let audio: AudioContext | null = null;
    setStatus("starting");
    const open = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        if (cancelled) {
          return;
        }
        audio = new AudioContext();
        const node = audio.createAnalyser();
        node.fftSize = 1024;
        audio.createMediaStreamSource(stream).connect(node);
        analyser.current = node;
        buffer.current = new Float32Array(node.fftSize);
        setStatus("on");
      } catch {
        if (!cancelled) {
          setStatus("blocked");
        }
      }
    };
    open();
    return () => {
      cancelled = true;
      analyser.current = null;
      for (const track of stream?.getTracks() ?? []) {
        track.stop();
      }
      audio?.close();
      setStatus("off");
    };
  }, [enabled]);

  const level = useCallback(() => {
    const node = analyser.current;
    const data = buffer.current;
    if (!(node && data)) {
      return 0;
    }
    node.getFloatTimeDomainData(data);
    let sum = 0;
    for (const sample of data) {
      sum += sample * sample;
    }
    // −55 dB (room) → 0, −15 dB (close, loud speech) → 1.
    const db = 10 * Math.log10(sum / data.length + 1e-10);
    return Math.min(Math.max((db + 55) / 40, 0), 1);
  }, []);

  return { level, status };
};

// ── Demo ─────────────────────────────────────────────────────────────────

/** The demo's script: each step's state, how long it holds, and its text. */
const SCRIPT: {
  eyebrow?: string;
  label?: string;
  ms: number;
  state: VoiceState;
}[] = [
  { ms: 3000, state: "listening" },
  { ms: 1800, state: "thinking" },
  { ms: 5200, state: "speaking" },
  {
    eyebrow: "Now playing",
    label: "Rain on Glass",
    ms: 6000,
    state: "playing",
  },
];

/**
 * The built-in demo: press to run one conversation, press again to stop.
 * Its `level` makes up a voice; pass `mic` to hear yours while listening.
 */
export const useVoiceDemo = (mic?: () => number) => {
  const [step, setStep] = useState(-1);
  const stepRef = useRef(step);
  stepRef.current = step;
  const micRef = useRef(mic);
  micRef.current = mic;

  useEffect(() => {
    const current = SCRIPT[step];
    if (!current) {
      return;
    }
    const timer = setTimeout(() => {
      setStep((s) => (s + 1 < SCRIPT.length ? s + 1 : -1));
    }, current.ms);
    return () => clearTimeout(timer);
  }, [step]);

  const level = useCallback(() => {
    const t = performance.now() / 1000;
    const state = SCRIPT[stepRef.current]?.state;
    if (state === "listening") {
      return micRef.current ? micRef.current() : speechLevel(t * 0.9) * 0.7;
    }
    if (state === "speaking") {
      return speechLevel(t);
    }
    return state === "playing" ? musicLevel(t) : 0;
  }, []);

  const current = SCRIPT[step];
  return {
    eyebrow: current?.eyebrow,
    label: current?.label,
    level,
    running: step >= 0,
    state: current?.state ?? ("idle" as VoiceState),
    toggle: () => setStep((s) => (s >= 0 ? -1 : 0)),
  };
};

// ── The block ────────────────────────────────────────────────────────────

/** The bars at rest: short, tall, short, so they read as a voice wave. */
const BARS_REST = [0.4, 0.75, 0.4];

/** Three bars that move with the level while the assistant is active. */
const LevelBars = ({
  active,
  level,
}: {
  active: boolean;
  level: VoiceLevel;
}) => {
  const bars = useRef<(HTMLSpanElement | null)[]>([]);
  const reduced = useReducedMotion() ?? false;
  const levelRef = useRef(level);
  levelRef.current = level;

  useEffect(() => {
    if (!active || reduced) {
      for (const [i, bar] of bars.current.entries()) {
        bar?.style.setProperty("transform", `scaleY(${BARS_REST[i]})`);
      }
      return;
    }
    let frame = 0;
    let smooth = 0;
    let last = 0;
    const tick = (now: number) => {
      const dt = last ? Math.min((now - last) / 1000, 0.05) : 0;
      last = now;
      const target = readLevel(levelRef.current);
      smooth = approach(
        smooth,
        target,
        target > smooth ? EASE.attack : EASE.release,
        dt
      );
      const t = now / 1000;
      for (const [i, bar] of bars.current.entries()) {
        const wiggle = 0.5 + 0.5 * Math.sin(t * (5 + i * 2.3) + i);
        const reach = i === 1 ? 1 : 0.55 + 0.45 * wiggle;
        const scale = Math.min(1, BARS_REST[i] + 0.6 * smooth * reach);
        bar?.style.setProperty("transform", `scaleY(${scale})`);
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active, reduced]);

  return (
    <span className="flex h-4 items-center gap-[3px]">
      {[0, 1, 2].map((i) => (
        <span
          className={cn(
            "h-full w-[3px] rounded-full bg-current",
            // The frame loop drives them while active; back to rest eases.
            !active && "transition-transform duration-300 ease-out"
          )}
          key={i}
          ref={(node) => {
            bars.current[i] = node;
          }}
          style={{ transform: `scaleY(${BARS_REST[i]})` }}
        />
      ))}
    </span>
  );
};

const MicIcon = () => (
  <svg
    aria-hidden
    className="size-3.5"
    fill="none"
    stroke="currentColor"
    strokeLinecap="round"
    strokeLinejoin="round"
    strokeWidth={1.75}
    viewBox="0 0 24 24"
  >
    <rect height="12" rx="3" width="6" x="9" y="3" />
    <path d="M5 11a7 7 0 0 0 14 0M12 18v3" />
  </svg>
);

export interface VoiceOrbProps extends Omit<ComponentProps<"div">, "onToggle"> {
  /**
   * What the assistant is doing. Leave it out for the built-in demo, which
   * runs one conversation when the button is pressed.
   */
  state?: VoiceState;
  /** Voice level 0–1, or a function read every frame (see `useMicLevel`). */
  level?: VoiceLevel;
  /** The text in the middle. Defaults to the state's own word. */
  label?: string;
  /** A small line above the label, e.g. "Now playing". */
  eyebrow?: string;
  /** Called when the talk button is pressed (controlled use). */
  onToggle?: () => void;
  /** The talk button's accessible name. Defaults by state. */
  buttonLabel?: string;
  /**
   * Show the talk button (and, in the demo, the mic toggle). Turn it off
   * when your own UI drives `state`. Defaults to true.
   */
  showControls?: boolean;
}

export const VoiceOrb = ({
  buttonLabel,
  className,
  eyebrow,
  label,
  level,
  onToggle,
  showControls = true,
  state,
  ...props
}: VoiceOrbProps) => {
  const [micOn, setMicOn] = useState(false);
  const mic = useMicLevel(micOn);
  const demo = useVoiceDemo(mic.status === "on" ? mic.level : undefined);
  const isDemo = state === undefined;

  const shown = isDemo ? demo.state : state;
  const text = (isDemo ? demo.label : label) ?? LABELS[shown];
  const above = isDemo ? demo.eyebrow : eyebrow;
  const voice = isDemo ? demo.level : (level ?? 0);
  const active = shown !== "idle";

  return (
    <div
      className={cn("flex w-full max-w-sm flex-col items-center", className)}
      data-slot="voice-orb"
      {...props}
    >
      <div className="relative aspect-square w-full">
        <ParticleOrb className="absolute inset-0" level={voice} state={shown} />
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center px-[20%] text-center">
          <div className="relative">
            <AnimatePresence initial={false}>
              {above ? (
                <motion.p
                  animate={{ filter: "blur(0px)", opacity: 1, y: 0 }}
                  className="text-muted-foreground absolute inset-x-0 bottom-full mb-1.5 text-[0.625rem] font-medium tracking-[0.2em] whitespace-nowrap uppercase"
                  exit={{ filter: "blur(2px)", opacity: 0, y: -4 }}
                  initial={{ filter: "blur(2px)", opacity: 0, y: 4 }}
                  key={above}
                  transition={{ duration: 0.3, ease: [0.23, 1, 0.32, 1] }}
                >
                  {above}
                </motion.p>
              ) : null}
            </AnimatePresence>
            <TextMorph
              as="p"
              className="text-foreground text-lg tracking-tight whitespace-nowrap"
              duration={TEXT_MORPH.duration}
              ease={TEXT_MORPH.ease}
              respectReducedMotion
            >
              {text}
            </TextMorph>
          </div>
        </div>
      </div>

      {showControls ? (
        <div className="mt-6 flex flex-col items-center gap-3">
          <Button
            aria-label={buttonLabel ?? (active ? "Stop" : "Start talking")}
            aria-pressed={active}
            className="size-14 rounded-full"
            onClick={isDemo ? demo.toggle : onToggle}
            size="icon"
            variant="outline"
          >
            <LevelBars active={active} level={voice} />
          </Button>
          {isDemo ? (
            <Button
              aria-pressed={micOn}
              className="text-muted-foreground h-7 gap-1.5 rounded-full px-2.5 text-xs"
              onClick={() => setMicOn((on) => !on)}
              size="sm"
              variant="ghost"
            >
              <MicIcon />
              {mic.status === "blocked" ? "Mic blocked" : "Use my mic"}
            </Button>
          ) : null}
        </div>
      ) : null}

      <p aria-live="polite" className="sr-only">
        {above ? `${above}: ${text}` : text}
      </p>
    </div>
  );
};

export default VoiceOrb;

// The orb's drawing, in plain WebGL2 (no React, no libraries).
//
// One ball of points: each point is a direction on the unit sphere plus a
// few random numbers. Everything that moves is worked out per frame on the
// GPU from a handful of numbers (OrbLook), so a state change in the block is
// only those numbers easing to new values; nothing is rebuilt.
//
//   shell       points sit at radius × (1 + jitter × thickness)
//   rim light   points seen edge-on are bright, points facing you faint,
//               which is what makes a ball of dots read as a ring
//   wobble      slow 3D noise bends the whole ball (music)
//   ripple      faster noise, scaled by the voice level (speech)
//   twinkle     each point's brightness breathes on its own phase
//   iris        a pastel hue around the rim (music)
//
// Points are crisp discs with a 1px soft edge. There is no glow or bloom:
// the brightness comes from how many points overlap.

/** The numbers that make a state's look; the block eases between them. */
export interface OrbLook {
  /** Slow in-out of the radius, 0–1 (thinking). */
  breath: number;
  /** Overall opacity of the points, 0–1. */
  bright: number;
  /** How far each point wanders from its place, in radius units. */
  drift: number;
  /** Opacity of the points facing you, relative to the rim, 0–1. */
  front: number;
  /** Pastel hue around the rim, 0–1. */
  iris: number;
  /** How much the voice level moves the ball, 0–1. */
  levelGain: number;
  /** Radius of the ball, as a share of half the canvas. */
  radius: number;
  /** How quickly brightness falls from the rim to the middle. */
  rimPower: number;
  /** Speech ripple on the surface, scaled by the level, 0–1. */
  ripple: number;
  /** Point diameter in CSS pixels at a 360px orb. */
  size: number;
  /** Turns per second around the vertical axis. */
  spin: number;
  /** Depth of the shell, in radius units. */
  thickness: number;
  /** How much each point's brightness breathes, 0–1. */
  twinkle: number;
  /** Low, slow bend of the whole ball, in radius units. */
  wobble: number;
}

export interface OrbFrame {
  /** Point colour, 0–1 per channel. */
  color: readonly [number, number, number];
  /** Smoothed voice level, 0–1. */
  level: number;
  look: OrbLook;
  /** Rotation around the vertical axis, in radians. */
  spin: number;
  /** Seconds since start; held still under reduced motion. */
  time: number;
}

export interface OrbRenderer {
  dispose: () => void;
  draw: (frame: OrbFrame) => void;
  /** Canvas size in device pixels, and the orb's CSS size. */
  resize: (width: number, height: number, cssSize: number) => void;
}

/** The ball's forward tilt, so the top reads as a lid, in radians. */
const TILT = 0.32;

/** Points per orb. */
export const ORB_POINTS = 9000;

// ── Point cloud ──────────────────────────────────────────────────────────
// Deterministic, so the same orb draws the same every load.
/** A seeded sequence of 0–1 numbers (a sine hash: plenty for scatter). */
const seeded = (seed: number) => {
  let n = seed;
  return () => {
    n += 1;
    const x = Math.sin(n * 12.9898 + seed * 78.233) * 43_758.5453;
    return x - Math.floor(x);
  };
};

/** Mostly fine points, some larger ones and a few flakes that sparkle. */
const sizeFactor = (roll: number, spread: number) => {
  if (roll < 0.86) {
    return 0.5 + spread * 0.4;
  }
  if (roll < 0.97) {
    return 0.9 + spread * 0.4;
  }
  return 1.4 + spread * 0.5;
};

/**
 * Per point: direction (xyz) then jitter, size, phase, rate (4 numbers).
 * Directions follow a Fibonacci sphere, nudged so no lattice shows.
 */
export const orbPoints = (count = ORB_POINTS) => {
  const random = seeded(7);
  const data = new Float32Array(count * 7);
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < count; i += 1) {
    const y = 1 - (2 * (i + 0.5)) / count;
    const ring = Math.sqrt(1 - y * y);
    const angle = i * golden;
    let x = Math.cos(angle) * ring + (random() - 0.5) * 0.06;
    let z = Math.sin(angle) * ring + (random() - 0.5) * 0.06;
    let yy = y + (random() - 0.5) * 0.06;
    const length = Math.hypot(x, yy, z) || 1;
    x /= length;
    yy /= length;
    z /= length;
    // Three rolls summed: most points near the middle of the shell.
    const jitter = (random() + random() + random() - 1.5) / 1.5;
    const o = i * 7;
    data[o] = x;
    data[o + 1] = yy;
    data[o + 2] = z;
    data[o + 3] = jitter;
    data[o + 4] = sizeFactor(random(), random());
    data[o + 5] = random();
    data[o + 6] = random();
  }
  return data;
};

/** The 3×3 rotation (column-major) for a spin, then the fixed tilt. */
export const orbRotation = (spin: number) => {
  const cy = Math.cos(spin);
  const sy = Math.sin(spin);
  const cx = Math.cos(TILT);
  const sx = Math.sin(TILT);
  // Rx(TILT) · Ry(spin)
  return new Float32Array([
    cy,
    sx * sy,
    -cx * sy,
    0,
    cx,
    sx,
    sy,
    -sx * cy,
    cx * cy,
  ]);
};

/**
 * A still orb on a 2D canvas, for browsers without WebGL2: the same points
 * and rim light, no motion. `width`/`height` are device pixels.
 */
export const drawOrbStill = (
  canvas: HTMLCanvasElement,
  color: readonly [number, number, number],
  look: OrbLook
) => {
  const ctx = canvas.getContext("2d");
  if (!ctx) {
    return;
  }
  const { height, width } = canvas;
  const half = Math.min(width, height) / 2;
  // Device pixels per CSS pixel at a 360px orb, as in the shader.
  const px =
    ((width / Math.max(canvas.clientWidth, 1)) *
      Math.min(canvas.clientWidth, canvas.clientHeight)) /
    360;
  const points = orbPoints(2600);
  const m = orbRotation(0.6);
  const [r, g, b] = color.map((c) => Math.round(c * 255));
  ctx.clearRect(0, 0, width, height);
  for (let o = 0; o < points.length; o += 7) {
    const [x, y, z] = [points[o], points[o + 1], points[o + 2]];
    const nx = m[0] * x + m[3] * y + m[6] * z;
    const ny = m[1] * x + m[4] * y + m[7] * z;
    const nz = m[2] * x + m[5] * y + m[8] * z;
    const radius = look.radius * (1 + points[o + 3] * look.thickness);
    const rim = (1 - Math.abs(nz)) ** look.rimPower;
    const alpha = look.bright * (look.front + (1 - look.front) * rim);
    ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${alpha * (nz < 0 ? 0.3 : 1)})`;
    ctx.beginPath();
    ctx.arc(
      width / 2 + nx * radius * half,
      height / 2 - ny * radius * half,
      Math.max(0.5, (look.size * points[o + 4] * px) / 2),
      0,
      Math.PI * 2
    );
    ctx.fill();
  }
};

// ── Shaders ──────────────────────────────────────────────────────────────
// Simplex noise: Ashima Arts / Stefan Gustavson (MIT).
const NOISE = `
vec4 permute(vec4 x) { return mod(((x * 34.0) + 1.0) * x, 289.0); }
vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }
float snoise(vec3 v) {
  const vec2 C = vec2(1.0 / 6.0, 1.0 / 3.0);
  const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
  vec3 i = floor(v + dot(v, C.yyy));
  vec3 x0 = v - i + dot(i, C.xxx);
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min(g.xyz, l.zxy);
  vec3 i2 = max(g.xyz, l.zxy);
  vec3 x1 = x0 - i1 + C.xxx;
  vec3 x2 = x0 - i2 + 2.0 * C.xxx;
  vec3 x3 = x0 - 1.0 + 3.0 * C.xxx;
  i = mod(i, 289.0);
  vec4 p = permute(permute(permute(
    i.z + vec4(0.0, i1.z, i2.z, 1.0)) +
    i.y + vec4(0.0, i1.y, i2.y, 1.0)) +
    i.x + vec4(0.0, i1.x, i2.x, 1.0));
  float n_ = 1.0 / 7.0;
  vec3 ns = n_ * D.wyz - D.xzx;
  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_);
  vec4 x = x_ * ns.x + ns.yyyy;
  vec4 y = y_ * ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);
  vec4 b0 = vec4(x.xy, y.xy);
  vec4 b1 = vec4(x.zw, y.zw);
  vec4 s0 = floor(b0) * 2.0 + 1.0;
  vec4 s1 = floor(b1) * 2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));
  vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
  vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
  vec3 p0 = vec3(a0.xy, h.x);
  vec3 p1 = vec3(a0.zw, h.y);
  vec3 p2 = vec3(a1.xy, h.z);
  vec3 p3 = vec3(a1.zw, h.w);
  vec4 norm = taylorInvSqrt(vec4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
  vec4 m = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
  m = m * m;
  return 42.0 * dot(m * m, vec4(dot(p0, x0), dot(p1, x1), dot(p2, x2), dot(p3, x3)));
}
`;

const VERTEX = `#version 300 es
precision highp float;
in vec3 aDir;
in vec4 aSeed; // jitter, size, phase, rate
uniform mat3 uRot;
uniform vec2 uFit;      // clip units per radius unit, x and y
uniform float uPx;      // device pixels per CSS pixel at a 360px orb
uniform float uTime;
uniform float uLevel;
uniform vec3 uColor;
// look
uniform float uBreath, uBright, uDrift, uFront, uIris, uRadius, uRimPower;
uniform float uRipple, uSize, uThickness, uTwinkle, uWobble;
out float vAlpha;
out vec3 vColor;
${NOISE}
void main() {
  vec3 d = aDir;
  float t = uTime;
  float bend = snoise(d * 1.35 + vec3(0.0, t * 0.32, t * 0.21));
  float ripple = snoise(d * 2.8 + vec3(t * 0.9, -t * 0.7, t * 0.5));
  float r = uRadius * (
    1.0
    + uLevel * 0.05
    + sin(t * 1.9) * 0.018 * uBreath
    + bend * uWobble
    + ripple * uRipple * uLevel * 0.07
    + aSeed.x * (uThickness + uLevel * 0.035)
  );
  vec3 p = d * r;
  float ph = aSeed.z * 6.2831;
  p += uDrift * vec3(sin(t * 0.7 + ph), cos(t * 0.61 + ph * 1.3), sin(t * 0.53 + ph * 0.7));
  p = uRot * p;
  vec3 n = uRot * d;

  float rim = pow(1.0 - abs(n.z), uRimPower);
  float back = mix(0.3, 1.0, smoothstep(-0.25, 0.25, n.z));
  float twinkle = 1.0 - uTwinkle * 0.5 * (1.0 + sin(t * (1.2 + aSeed.w * 2.4) + ph));
  vAlpha = clamp((uBright + uLevel * 0.22) * mix(uFront, 1.0, rim) * back * twinkle, 0.0, 1.0);

  // Iris: cyan → lilac → pink around the rim, turning slowly. On light
  // themes (dark points) the same hues, deeper, so they hold on white.
  float hue = fract(atan(n.y, n.x) / 6.2831 + t * 0.04) * 3.0;
  vec3 cyan = vec3(0.56, 0.86, 1.0);
  vec3 lilac = vec3(0.78, 0.68, 1.0);
  vec3 pink = vec3(1.0, 0.72, 0.88);
  vec3 tint = hue < 1.0 ? mix(cyan, lilac, hue)
    : hue < 2.0 ? mix(lilac, pink, hue - 1.0)
    : mix(pink, cyan, hue - 2.0);
  float light = dot(uColor, vec3(0.2126, 0.7152, 0.0722));
  tint *= mix(0.58, 1.0, light);
  vColor = mix(uColor, tint, clamp(uIris * (0.35 + 0.65 * rim), 0.0, 1.0));

  float persp = 1.0 / (1.0 - p.z * 0.28);
  gl_Position = vec4(p.xy * persp * uFit, 0.0, 1.0);
  gl_PointSize = max(1.0, uSize * aSeed.y * persp * uPx * (1.0 + uLevel * 0.3));
}
`;

const FRAGMENT = `#version 300 es
precision mediump float;
in float vAlpha;
in vec3 vColor;
out vec4 outColor;
void main() {
  vec2 c = gl_PointCoord * 2.0 - 1.0;
  float d = dot(c, c);
  if (d > 1.0 || vAlpha < 0.004) discard;
  float a = vAlpha * (1.0 - smoothstep(0.5, 1.0, d));
  outColor = vec4(vColor * a, a);
}
`;

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

const link = (gl: WebGL2RenderingContext) => {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) {
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  return program;
};

const LOOK_UNIFORMS = {
  breath: "uBreath",
  bright: "uBright",
  drift: "uDrift",
  front: "uFront",
  iris: "uIris",
  radius: "uRadius",
  rimPower: "uRimPower",
  ripple: "uRipple",
  size: "uSize",
  thickness: "uThickness",
  twinkle: "uTwinkle",
  wobble: "uWobble",
} as const satisfies Partial<Record<keyof OrbLook, string>>;

/** A renderer on `canvas`, or null when the browser has no WebGL2. */
export const createOrbRenderer = (
  canvas: HTMLCanvasElement
): OrbRenderer | null => {
  const gl = canvas.getContext("webgl2", {
    alpha: true,
    antialias: false,
    depth: false,
    premultipliedAlpha: true,
    stencil: false,
  });
  const program = gl ? link(gl) : null;
  if (!(gl && program)) {
    return null;
  }

  const points = orbPoints();
  const vao = gl.createVertexArray();
  const buffer = gl.createBuffer();
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, points, gl.STATIC_DRAW);
  const stride = 7 * 4;
  const dir = gl.getAttribLocation(program, "aDir");
  const seed = gl.getAttribLocation(program, "aSeed");
  gl.enableVertexAttribArray(dir);
  gl.vertexAttribPointer(dir, 3, gl.FLOAT, false, stride, 0);
  gl.enableVertexAttribArray(seed);
  gl.vertexAttribPointer(seed, 4, gl.FLOAT, false, stride, 3 * 4);
  gl.bindVertexArray(null);

  const at = (name: string) => gl.getUniformLocation(program, name);
  const uniforms = {
    color: at("uColor"),
    fit: at("uFit"),
    level: at("uLevel"),
    px: at("uPx"),
    rot: at("uRot"),
    time: at("uTime"),
  };
  const look = Object.fromEntries(
    Object.entries(LOOK_UNIFORMS).map(([key, name]) => [key, at(name)])
  ) as Record<keyof typeof LOOK_UNIFORMS, WebGLUniformLocation | null>;

  let fit: [number, number] = [1, 1];
  let px = 1;

  return {
    dispose: () => {
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.deleteProgram(program);
    },
    draw: (frame) => {
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.useProgram(program);
      gl.uniformMatrix3fv(uniforms.rot, false, orbRotation(frame.spin));
      gl.uniform2f(uniforms.fit, fit[0], fit[1]);
      gl.uniform1f(uniforms.px, px);
      gl.uniform1f(uniforms.time, frame.time);
      gl.uniform1f(uniforms.level, frame.level * frame.look.levelGain);
      gl.uniform3f(uniforms.color, ...frame.color);
      for (const key of Object.keys(LOOK_UNIFORMS) as (keyof typeof look)[]) {
        gl.uniform1f(look[key], frame.look[key]);
      }
      gl.bindVertexArray(vao);
      gl.drawArrays(gl.POINTS, 0, points.length / 7);
      gl.bindVertexArray(null);
    },
    resize: (width, height, cssSize) => {
      canvas.width = width;
      canvas.height = height;
      const side = Math.min(width, height);
      fit = [side / width, side / height];
      px = (width / Math.max(canvas.clientWidth, 1)) * (cssSize / 360);
    },
  };
};
